I think the appropriate fix is something like:
```rust
impl<T, const N: usize> !Iterator for [T; N] {} // if needed

impl<T, const N: usize, A: Allocator> IntoIterator for Box<[T; N], A> {
    type Item = T;
    type IntoIter = std::vec::IntoIter<T, A>; // we could use std::array::IntoIter, but that's less efficient

    fn into_iter(self) -> Self::IntoIter {
        Vec::<T, A>::from(self).into_iter()
    }
}

impl<'a, T, const N: usize, A: Allocator> IntoIterator for &'a Box<[T; N], A> {
    type Item = &'a T;
    type IntoIter = std::slice::Iter<'a, T>;

    fn into_iter(self) -> Self::IntoIter {
        self.iter()
    }
}

impl<'a, T, const N: usize, A: Allocator> IntoIterator for &'a mut Box<[T; N], A> {
    type Item = &'a mut T;
    type IntoIter = std::slice::IterMut<'a, T>;

    fn into_iter(self) -> Self::IntoIter {
        self.iter_mut()
    }
}
```

