Here is a refactor that is about 7% easier to read (imo)
<details>
<summary>expand</summary>

```rust
#![feature(allocator_api)]

use std::{alloc::Allocator, cell::Cell, marker::PhantomPinned, pin::Pin};

#[pin_project::pin_project]
struct TakeOnClone<T, A> {
    #[pin]
    val: Option<T>,
    cell: Cell<Option<(T, A)>>,
}
impl<T, A: Allocator> Clone for Box<TakeOnClone<T, A>, A> {
    fn clone(&self) -> Self {
        let (t, a) = self.cell.take().unwrap();
        let pointee = TakeOnClone {
            val: Some(t),
            cell: Cell::new(None),
        };
        Box::new_in(pointee, a)
    }
}

fn pin_in_short_alloc<'a, T, A>(
    victim: T,
    a_short: &'a A,
    a_long: &'static A,
) -> Pin<Box<TakeOnClone<T, &'a A>, &'a A>>
where
    for<'b> &'b A: Allocator,
{
    let deferred = TakeOnClone {
        val: None,
        cell: Cell::new(Some((victim, a_short))),
    };
    let payload: Pin<Box<TakeOnClone<T, &'a A>, &'static A>> = Box::pin_in(deferred, a_long);
    let payload: Pin<Box<TakeOnClone<T, &'a A>, &'a A>> = payload; // subtype coercion
    payload.clone() // result is allocated in a_short and then pinned by `Clone for Pin<T: Clone>`
}

pub fn main() {
    struct Victim(#[expect(dead_code)] [u8; 1024], PhantomPinned);
    impl Drop for Victim {
        fn drop(&mut self) {
            unreachable!("never called")
        }
    }
    let victim = Victim([0; _], PhantomPinned);

    use bumpalo::Bump;

    let mut a_short = Bump::new();
    let mut pin_in_short = pin_in_short_alloc(victim, &a_short, Box::leak(Box::new(Bump::new())));

    let proof: Pin<&mut Victim> = pin_in_short.as_mut().project().val.as_pin_mut().unwrap();
    println!("pinned: {proof:p}"); // pinned: 0x5634eb7a2939

    std::mem::forget(pin_in_short); // short borrow ends
    a_short.reset(); // allocator no longer borrowed, but pinned value was never dropped!

    let reuse = a_short.alloc([0u8; 1024]);
    println!("reused: {reuse:p}"); // reused: 0x5634eb7a2940
}
```
</details>

