Your benchmark is broken: since the result of the search is never utilised, LLVM will optimise out the call of `fast` since it knows it to be side-effect-free. `slow` is still called however. In actuality, `slow` is quite a lot faster than `fast` – though its still beaten by the native `memchr` implementation.

```rust
use std::hint::black_box;

fn main() {
    let tests = [
        "saddasadadsadafdsdafhsdfjhsdkjgfhfskdgvhsdjgfhsjagsjagduagfjhsdagfysdagfusdfhsds",
        ".",
        "skdghsdhjajgdsdasdsafdsdaffdsfdsfhgasdgfhdsa.afdjhasdhjghsajdhasgdhjasd",
        "\u{ad}\u{ad}.\u{ad}\u{ad}",
        "",
    ];

    for test in tests {
        println!("{test:?}");

        let timer = std::time::Instant::now();
        for _ in 0..1_000_000 {
            black_box(slow(black_box(test)));
        }
        println!("  Slow: {:?}", timer.elapsed());

        let timer = std::time::Instant::now();
        for _ in 0..1_000_000 {
            black_box(fast(black_box(test)));
        }
        println!("  Fast: {:?}", timer.elapsed());

        let timer = std::time::Instant::now();
        for _ in 0..1_000_000 {
            black_box(platform(black_box(test)));
        }
        println!("  Memchr: {:?}", timer.elapsed());

        println!();
    }
}

#[inline(never)]
fn slow(x: &str) -> bool {
    x.contains('.')
}

#[inline(never)]
fn fast(x: &str) -> bool {
    x.as_bytes().iter().any(|&b| b == b'.')
}

unsafe extern "C" {
    unsafe fn memchr(ptr: *const u8, val: i32, len: usize) -> *const u8;
}

#[inline(never)]
fn platform(x: &str) -> bool {
    unsafe {
        let r = memchr(x.as_bytes().as_ptr(), b'.' as i32, x.len());
        !r.is_null()
    }
}
```
